-- Player's Handbook v3.5 source-backed core rules catalog.
-- Mechanical summaries are concise/paraphrased; the supplied sourcebook and bundled errata remain authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('phb-3.5','players-handbook-3-5','Player''s Handbook','PHB','Wizards of the Coast','dnd','3.5',
        'Core Rulebook I; source for D&D v3.5 player-facing character, skill, combat, adventuring, and spellcasting rules, including supplied errata.',NULL,1,0,NULL);

WITH desired(slug,name,source_page,category,kind,summary,tags,mechanics) AS (VALUES
  ('phb-core-mechanic','The Core Mechanic','5','checks','rule','When an action has a chance of failure, roll a d20, add the relevant modifiers, and succeed if the result equals or exceeds the target number.','["core","d20","checks"]','{"die":"d20","success":"result >= target"}'),
  ('phb-ability-score-generation','Standard Ability Score Generation','7','character-creation','procedure','Generate each starting ability score by rolling four d6, discarding the lowest die, and totaling the other three; repeat six times and assign the results.','["character-creation","abilities"]','{"roll":"4d6 drop lowest","scores":6,"minimum":3,"maximum":18}'),
  ('phb-low-ability-reroll','Low Ability Score Reroll','8','character-creation','rule','The standard rolled array may be discarded and rerolled when its total pre-racial ability modifiers are 0 or lower or when its highest score is 13 or lower.','["character-creation","abilities","reroll"]','{"reroll_if_modifier_sum_lte":0,"reroll_if_highest_score_lte":13}'),
  ('phb-ability-modifiers','Ability Modifiers','8','abilities','table','Ability modifiers increase by 1 for every two points above 10 and decrease similarly below 10, as shown on the ability-modifier table.','["abilities","modifiers"]','{"formula":"floor((score - 10) / 2)"}'),
  ('phb-spellcasting-minimum-ability','Minimum Ability for Spellcasting','8','magic','rule','A spellcaster needs a governing ability score of at least 10 plus the spell level to cast a spell of that level.','["magic","spellcasting","abilities"]','{"minimum_ability":"10 + spell level"}'),
  ('phb-skill-check','Skill Checks','63','skills','rule','A skill check is 1d20 plus skill ranks, the key ability modifier, and other applicable modifiers, compared with a DC or an opposed result.','["skills","checks","d20"]','{"roll":"1d20 + ranks + ability modifier + other modifiers"}'),
  ('phb-skill-natural-rolls','Natural Rolls on Skill Checks','63','skills','rule','Natural 20 and natural 1 are not automatic success or failure on skill checks.','["skills","checks","natural-roll"]','{"natural_20_auto_success":false,"natural_1_auto_failure":false}'),
  ('phb-skill-rank-limits','Skill Rank Limits','62','skills','rule','Maximum class-skill ranks equal character level + 3; maximum cross-class ranks are half that amount, and cross-class ranks cost twice as many skill points.','["skills","ranks","advancement"]','{"class_max":"character level + 3","cross_class_max":"(character level + 3) / 2","class_rank_cost":1,"cross_class_rank_cost":2}'),
  ('phb-take-10','Taking 10','65','skills','rule','When not threatened or distracted and the skill permits it, a character can treat the d20 result as 10 instead of rolling.','["skills","take-10"]','{"die_result":10,"requires_no_threat_or_distraction":true}'),
  ('phb-take-20','Taking 20','65','skills','rule','When repeated attempts carry no penalty for failure and sufficient time is available, a character can treat the check as though a 20 was rolled, consuming twenty times the normal check time.','["skills","take-20"]','{"die_result":20,"time_multiplier":20,"requires_no_failure_penalty":true}'),
  ('phb-aid-another-skill','Aid Another on Skill Checks','65','skills','rule','A helper who can reasonably assist makes the relevant check against DC 10; success normally gives the acting character a +2 circumstance bonus.','["skills","aid-another"]','{"aid_dc":10,"circumstance_bonus":2}'),
  ('phb-feat-prerequisites','Feat Prerequisites','87','feats','rule','A character must meet a feat''s prerequisites to select it and cannot use a feat while a prerequisite is no longer met, unless the feat says otherwise.','["feats","prerequisites"]','{"must_meet_to_select":true,"must_meet_to_use":true}'),
  ('phb-battle-grid-scale','Battle Grid Scale','135','combat','rule','On the standard battle grid, each 1-inch square represents a 5-foot square in the game world.','["combat","grid","distance"]','{"square_feet":5}'),
  ('phb-combat-round','Combat Rounds','135','combat','rule','Combat proceeds in rounds, and each round represents 6 seconds in the game world.','["combat","rounds","time"]','{"seconds_per_round":6}'),
  ('phb-initiative','Initiative','135-136','combat','procedure','Before combat, each combatant makes a Dexterity check for initiative; creatures act from highest result to lowest and normally keep that order for the battle.','["combat","initiative"]','{"check":"1d20 + Dexterity modifier","order":"descending"}'),
  ('phb-flat-footed-before-acting','Flat-Footed before Acting','135','combat','rule','A combatant is flat-footed until taking an action in combat and therefore normally loses Dexterity bonus to Armor Class.','["combat","flat-footed","initiative"]','{"ends_after_first_action":true,"loses_dex_bonus_to_ac":true}'),
  ('phb-action-economy','Actions in a Round','135','combat','rule','On a normal turn a character can take a standard action and a move action in either order, two move actions, or one full-round action, plus permitted free actions.','["combat","actions","action-economy"]','{"normal_options":[["standard","move"],["move","move"],["full-round"]],"free_actions_allowed":true}'),
  ('phb-surprise-round','Surprise Round','137','combat','procedure','If some but not all combatants are aware when combat begins, aware combatants roll initiative and may take one standard action plus permitted free actions in the surprise round.','["combat","surprise","initiative"]','{"aware_actions":["standard","free"],"occurs_if":"some but not all combatants are aware"}'),
  ('phb-unaware-in-surprise','Unaware Combatants in Surprise','137','combat','rule','Combatants unaware when combat begins do not act in the surprise round and are flat-footed until they act.','["combat","surprise","flat-footed"]','{"acts_in_surprise_round":false,"flat_footed":true}'),
  ('phb-threatened-squares','Threatened Squares','137','combat','rule','A creature threatens squares into which it can make a melee attack, even when it is not that creature''s turn.','["combat","attacks-of-opportunity","threatened"]','{}'),
  ('phb-attacks-of-opportunity','Attacks of Opportunity','137-138','combat','rule','Leaving a threatened square or performing certain distracting actions can provoke a free melee attack from a threatening opponent; specific exceptions such as a 5-foot step can avoid provoking.','["combat","attacks-of-opportunity","movement"]','{"common_triggers":["leave threatened square","distracting action"],"five_foot_step_provokes":false}'),
  ('phb-attack-roll','Attack Rolls','135','combat','rule','An attack hits when its d20 attack result equals or exceeds the target''s Armor Class. Melee attacks normally use Strength; ranged attacks normally use Dexterity.','["combat","attack-roll","armor-class"]','{"success":"attack result >= AC","melee_ability":"Strength","ranged_ability":"Dexterity"}'),
  ('phb-automatic-attack-results','Automatic Misses and Hits','139','combat','rule','A natural 1 on an attack roll always misses and a natural 20 always hits and also threatens a critical hit.','["combat","attack-roll","natural-roll"]','{"natural_1":"automatic miss","natural_20":"automatic hit and critical threat"}'),
  ('phb-critical-hits','Critical Hits','140','combat','rule','When an attack roll falls in the weapon''s threat range, make another attack roll to confirm; a successful confirmation applies the weapon''s critical multiplier.','["combat","critical-hit"]','{"confirmation_required":true,"confirmation":"attack roll must hit"}'),
  ('phb-total-defense','Total Defense','142','combat','rule','As a standard action, total defense grants a +4 dodge bonus to AC for 1 round, prevents attacks of opportunity by the defender, and cannot be combined with fighting defensively or Combat Expertise.','["combat","defense","actions"]','{"action":"standard","dodge_bonus_ac":4,"duration_rounds":1,"can_make_aoo":false}'),
  ('phb-five-foot-step','5-Foot Step','144','movement','rule','A character can normally move 5 feet without provoking attacks of opportunity when no other movement is taken during the round and the step is not through difficult terrain.','["combat","movement","five-foot-step"]','{"distance_feet":5,"provokes_aoo":false,"other_movement_allowed":false}'),
  ('phb-charge','Charge','154','combat','rule','Charging is a special full-round action that moves up to twice speed in a sufficiently straight, clear path and ends with a melee attack that gains +2 to hit and imposes -2 AC until the next turn.','["combat","charge","movement"]','{"action":"full-round","max_speed_multiplier":2,"attack_bonus":2,"ac_penalty":-2}'),
  ('phb-withdraw','Withdraw','143','combat','rule','Withdrawing is a full-round action that allows movement up to twice speed and makes the square where movement begins not count as threatened for provoking from that movement.','["combat","withdraw","movement"]','{"action":"full-round","max_speed_multiplier":2,"starting_square_not_threatened_for_withdrawal":true}'),
  ('phb-run','Run','144','movement','rule','Running is normally a full-round action that moves four times speed in a straight line, or three times speed in heavy armor, while sacrificing normal Dexterity bonus to AC.','["movement","run","combat"]','{"action":"full-round","normal_speed_multiplier":4,"heavy_armor_speed_multiplier":3,"loses_dex_bonus_to_ac":true}'),
  ('phb-delay','Delay','160','combat','procedure','A combatant may voluntarily act later in the initiative order and thereafter uses the new initiative position.','["combat","initiative","delay"]','{}'),
  ('phb-ready','Ready','160','combat','procedure','Ready is a standard action that specifies an action and a trigger; when the trigger occurs before the character''s next turn, the readied action can interrupt according to the ready rules and changes initiative position.','["combat","initiative","ready"]','{"action":"standard","requires_trigger":true,"changes_initiative":true}'),
  ('phb-grapple','Grapple','155-157','combat','subsystem','Grappling uses touch attacks, opposed grapple checks, and a defined set of actions for grabbing, holding, damaging, moving, pinning, and escaping.','["combat","grapple","special-attack"]','{"grapple_check":"base attack bonus + Strength modifier + special size modifier"}'),
  ('phb-bull-rush','Bull Rush','154-155','combat','procedure','A bull rush attempts to push an opponent back through opposed Strength checks modified by size and stability; movement while initiating it can provoke as specified by the special-attack rules.','["combat","bull-rush","special-attack"]','{"opposed_check":"Strength"}'),
  ('phb-disarm','Disarm','155','combat','procedure','A disarm attempt uses opposed attack rolls with modifiers for weapon size, weapon handedness, and related circumstances; failure can permit the defender to counter-disarm.','["combat","disarm","special-attack"]','{"opposed_roll":"attack roll"}'),
  ('phb-trip','Trip','158','combat','procedure','A trip attack begins with a melee touch attack and, if successful, resolves an opposed Strength-versus-Strength-or-Dexterity check with size and stability modifiers.','["combat","trip","special-attack"]','{"initial_attack":"melee touch","defender_check_choice":["Strength","Dexterity"]}'),
  ('phb-sunder','Sunder','158','combat','procedure','Sundering attacks a held or carried object using the special attack procedure, then applies the object''s hardness and hit points to damage.','["combat","sunder","objects","special-attack"]','{}'),
  ('phb-two-weapon-fighting','Two-Weapon Fighting','160','combat','rule','Fighting with a second weapon grants an extra off-hand attack during a full attack but applies attack penalties that depend on weapon weight and feats.','["combat","two-weapon-fighting","full-attack"]','{"requires_full_attack":true,"extra_off_hand_attacks":1}'),
  ('phb-disabled','Disabled','145','injury','rule','At exactly 0 hit points, or when conscious while below 0 under a special rule, a character is disabled: only one standard or move action is available, movement is halved, and strenuous action normally deals 1 damage afterward.','["injury","disabled","hit-points"]','{"normal_hp":0,"allowed_actions":["standard","move"],"speed_multiplier":0.5,"strenuous_action_damage":1}'),
  ('phb-dying','Dying','145','injury','rule','A character at -1 through -9 hit points is unconscious and dying; each round the character has a chance to stabilize and otherwise continues losing hit points.','["injury","dying","hit-points"]','{"hp_min":-9,"hp_max":-1,"unconscious":true,"stabilize_percent":10}'),
  ('phb-death-hit-points','Death from Hit Point Loss','145','injury','rule','A character dies when current hit points reach -10 unless another rule changes the death threshold.','["injury","death","hit-points"]','{"death_at_hp":-10}'),
  ('phb-nonlethal-damage','Nonlethal Damage','146','injury','rule','Nonlethal damage is tracked separately from hit points; when it equals current hit points the creature is staggered, and when it exceeds current hit points the creature falls unconscious.','["injury","nonlethal","hit-points"]','{"staggered_when":"nonlethal >= current hp","unconscious_when":"nonlethal > current hp"}'),
  ('phb-carrying-capacity','Carrying Capacity','161-162','adventuring','table','Strength determines light, medium, and heavy load limits; lifting and dragging limits derive from maximum load, with size modifying capacity.','["adventuring","encumbrance","strength"]','{"lift_overhead":"maximum load","lift_off_ground_multiplier":2,"push_or_drag_multiplier":5}'),
  ('phb-hampered-movement','Hampered Movement','163','movement','rule','Difficult or obstructed terrain increases movement cost according to the hampered-movement rules; multiple applicable movement-cost multipliers combine by adding the extra costs rather than simply multiplying them.','["movement","terrain","adventuring"]','{}'),
  ('phb-concentration-defensive-casting','Casting Defensively','69,140','magic','rule','A spellcaster can avoid attacks of opportunity from casting by succeeding on a Concentration check with DC 15 + spell level; failure wastes the action and the spell.','["magic","concentration","attacks-of-opportunity"]','{"concentration_dc":"15 + spell level","success":"no attack of opportunity","failure":"spell lost and action wasted"}'),
  ('phb-spell-save-dc','Spell Saving Throw DC','169','magic','rule','The normal saving throw DC for a spell is 10 + spell level + the caster''s relevant spellcasting ability modifier.','["magic","saving-throws","dc"]','{"formula":"10 + spell level + casting ability modifier"}'),
  ('phb-spell-resistance','Spell Resistance','177','magic','rule','When spell resistance applies, the caster makes a caster-level check and must equal or exceed the target''s spell resistance for the spell to affect it.','["magic","spell-resistance","caster-level"]','{"check":"1d20 + caster level","success":"result >= spell resistance"}'),
  ('phb-dispel-check','Dispel Check','172,223','magic','rule','A dispel check is 1d20 + caster level against DC 11 + the caster level of the effect being dispelled, subject to the particular dispel effect''s limits.','["magic","dispel","caster-level"]','{"check":"1d20 + caster level","dc":"11 + effect caster level"}'),
  ('phb-line-of-effect','Line of Effect','175','magic','rule','A spell requires a clear line of effect to its target or point of origin; a solid barrier blocks line of effect unless the effect specifically says otherwise.','["magic","line-of-effect","targeting"]','{}'),
  ('phb-magic-effect-stacking','Combining Magical Effects','171-172','magic','rule','Bonuses of the same type generally do not stack, differently typed bonuses generally do, and multiple versions of the same effect follow the stronger/most recent/conflicting-effect rules as applicable.','["magic","stacking","bonuses"]','{"same_bonus_type_stacks":false,"different_bonus_types_stack":true}'),
  ('phb-primary-source-precedence','Primary Source Precedence','errata','adjudication','rule','Official errata controls conflicts. Otherwise text takes precedence over conflicting summary tables, and the book primary for a topic controls conflicting secondary sources; the Player''s Handbook is primary for gameplay, PC races, and base classes.','["errata","precedence","primary-source"]','{"text_over_table":true,"phb_primary_topics":["gameplay","pc_races","base_classes"]}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'phb-3.5-rule-' || d.slug, 'phb-3.5', d.source_page, d.slug, d.name, d.summary, d.summary,
  0,NULL,1,d.category,d.kind,0,1,NULL,NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.slug=d.slug AND r.owner_user_id IS NULL
);
